import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MessageType } from '../../enums/message-type.enums';
import { NewCard } from 'src/app/models/card/new-card.model';
import { CardUtils } from 'src/app/services/card/card-utils.service';
import { CardService } from 'src/app/services/card/card.service';

@Component({
  selector: 'app-add-card-modal',
  templateUrl: './add-card-modal.component.html',
  styleUrls: ['./add-card-modal.component.css']
})
export class AddCardModalComponent {
  public form: FormGroup;
  public type!: MessageType;
  public newCard!: NewCard;

  constructor(private fb: FormBuilder,private cardUtils: CardUtils, private cardService: CardService){
  console.log('chamando os forms ', fb)
    this.form = this.fb.group({
      titulo: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(50),
          Validators.required
        ])
      ],
      descricao: [
        '', Validators.compose([
          Validators.minLength(5),
          Validators.maxLength(150),
          Validators.required
        ])
      ],
    })
  }

  save(){
    // this.newCard = this.cardUtils.createNewCard(this.form);
    // console.log('chamando os forms ', this.newCard)

    this.cardUtils.createNewCard(this.form).subscribe({
      next: (card: NewCard) => {
        this.newCard = card;
        console.log('Novo cartão criado:', this.newCard);
      },
      error: (err) => {
        console.log('Erro ao criar o novo cartão:', err);
      }
    });

    this.cardService.addCard(this.newCard);
  }

}
